import { createClient } from "https://esm.sh/@supabase/supabase-js@2.45.4";
import { getCorsHeaders } from "./cors.ts";
import {
  addGraceHour,
  buildBookingDateUTC,
  getPinActivationStart,
  isBookingEnded,
  isWithinPinGenerationWindow,
} from "../_shared/pinTiming.ts";
import { ensurePinOnLock } from "../_shared/lockPin.ts";
import { getOAuthToken, GENERATE_PIN_SCOPES } from "../_shared/iglooAuth.ts";
const IGLOOHOME_API_BASE_URL = "https://api.igloodeveloper.co/igloohome";

/** Statuses eligible for customer portal + daily pin jobs */
const ELIGIBLE_BOOKING_STATUSES = [
  "Confirmed",
  "confirmed",
  "Delivered",
  "delivered",
  "waiting_to_be_returned",
  "Rescheduled",
  "rescheduled",
  "pending_verification",
  "pending_review",
];
function makeJsonResponse(corsHeaders) {
  return (body, status = 200) => new Response(JSON.stringify(body), {
    status,
    headers: {
      ...corsHeaders,
      "Content-Type": "application/json"
    }
  });
}
async function readResponse(res) {
  const text = await res.text();
  try {
    return {
      text,
      json: text ? JSON.parse(text) : null
    };
  } catch  {
    return {
      text,
      json: null
    };
  }
}
function generateRandomPin() {
  return String(Math.floor(Math.random() * 900000) + 100000);
}
/**
 * Parse a time slot string like "6:00 AM" or "11:00 PM" and convert MST -> UTC.
 * Returns an ISO string like "2026-05-06T12:00:00+00:00"
 *
 * MST is UTC-6, so we add 6 hours to convert local -> UTC.
 * If the UTC hour crosses midnight (>= 24), we roll to the next day.
 *
 * Falls back to the provided fallbackHourUTC if the slot cannot be parsed.
 */ function buildIgloohomeDate(date, timeSlot, fallbackHourUTC) {
  if (timeSlot && !timeSlot.trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i)) {
    console.warn(`[generate-pin] Could not parse time slot: "${timeSlot}" — using fallback`);
  }
  return buildBookingDateUTC(date, timeSlot, fallbackHourUTC);
}

async function maybeSendPinNotification(supabase, booking, pin, startTime, endTime) {
  if (booking.pin_notification_sent_at) return;
  const { error } = await supabase.functions.invoke("send-booking-confirmation", {
    body: {
      booking_id: booking.id,
      email_type: "pin_update",
      pin,
      start_time: startTime,
      end_time: endTime,
    },
  });
  if (error) {
    console.error(`[generate-pin] PIN notification failed for booking #${booking.id}:`, error.message);
    return;
  }
  const now = new Date().toISOString();
  await supabase.from("bookings").update({ pin_notification_sent_at: now }).eq("id", booking.id);
  await supabase.from("rental_access_codes").update({ notified_at: now }).eq("order_id", booking.id).eq("status", "active");
}
async function getOAuthTokenForPin(clientId, clientSecret) {
  const result = await getOAuthToken(clientId, clientSecret, GENERATE_PIN_SCOPES);
  console.log("[generate-pin] OAuth:", result.token ? `ok (${result.scopesUsed})` : result.reason);
  return result.token;
}
async function isLockOnline(accessToken, lockId) {
  const res = await fetch(`${IGLOOHOME_API_BASE_URL}/devices`, {
    method: "GET",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      Accept: "application/json"
    }
  });
  const body = await readResponse(res);
  if (!res.ok || !body.json?.payload) return false;
  const lock = body.json.payload.find((d)=>d.deviceId === lockId);
  if (!lock) return false;
  const bridge = body.json.payload.find((d)=>d.type === "Bridge" && d.linkedDevices?.length > 0);
  return !!bridge;
}
async function createBridgePin(accessToken, lockId, bridgeId, pin, startDate, endDate, accessName) {
  const url = `${IGLOOHOME_API_BASE_URL}/devices/${lockId}/jobs/bridges/${bridgeId}`;
  const payload = {
    jobType: 4,
    jobData: {
      accessName,
      pin,
      pinType: 4,
      startDate,
      endDate
    }
  };
  console.log("[generate-pin] Creating bridge PIN:", {
    url,
    payload
  });
  const res = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
      Accept: "application/json"
    },
    body: JSON.stringify(payload)
  });
  const body = await readResponse(res);
  console.log("[generate-pin] Bridge PIN response:", {
    status: res.status,
    body: body.json
  });
  if (!res.ok && res.status !== 201) {
    return {
      success: false,
      error: `Bridge PIN failed with status ${res.status}`
    };
  }
  return {
    success: true,
    pinId: body.json?.jobId || body.json?.pinId || body.json?.id || ""
  };
}
async function createAlgoPin(accessToken, lockId, dropOffDate, dropOffTimeSlot, pickupDate, orderId) {
  const startDate = buildIgloohomeDate(dropOffDate, dropOffTimeSlot, 12);
  // AlgoPIN requires zeroed minutes format: YYYY-MM-DDTHH:00:00+hh:mm
  // Round down to nearest whole hour so e.g. 05:10 becomes 05:00
  // This means the PIN activates slightly early rather than failing entirely
  const startDateHourOnly = startDate.replace(/T(\d{2}):\d{2}:00/, "T$1:00:00");
  const startUnix = new Date(startDateHourOnly).getTime() / 1000;
  const endUnix = new Date(pickupDate + "T23:59:59Z").getTime() / 1000;
  const variance = Math.min(5, Math.max(1, Math.ceil((endUnix - startUnix) / 86400)));
  const payload = {
    accessName: `Dump Loader Rental - Order #${orderId} (AlgoPIN)`,
    startDate: startDateHourOnly,
    variance
  };
  console.log("[generate-daily-pins] Creating AlgoPIN:", {
    url: `${IGLOOHOME_API_BASE_URL}/devices/${lockId}/algopin/onetime`,
    payload
  });
  const res = await fetch(`${IGLOOHOME_API_BASE_URL}/devices/${lockId}/algopin/onetime`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
      Accept: "application/json"
    },
    body: JSON.stringify(payload)
  });
  const body = await readResponse(res);
  console.log("[generate-daily-pins] AlgoPIN response:", {
    status: res.status,
    body: body.json
  });
  if (!res.ok && res.status !== 201) {
    return {
      success: false,
      error: `AlgoPIN failed with status ${res.status}`,
      rawResponse: body.json
    };
  }
  const pin = body.json?.pin || body.json?.access_code || body.json?.code || body.json?.data?.pin || "";
  if (!pin) return {
    success: false,
    error: "AlgoPIN succeeded but no PIN value in response"
  };
  return {
    success: true,
    pin,
    pinId: body.json?.pinId || body.json?.id || ""
  };
}
async function generatePinWithFallback(accessToken, lockId, bridgeId, supabase, booking) {
  const orderId = booking.id;
  const startDate = getPinActivationStart(booking);
  // PIN stays valid 1 hour past scheduled return so late returns still open the lock
  const endDate = addGraceHour(buildIgloohomeDate(booking.pickup_date, booking.pickup_time_slot, 5));
  console.log("[generate-pin] PIN window:", { startDate, endDate });
  const accessName = `Dump Loader Rental - Order #${orderId}`;

  const bridgeResult = await ensurePinOnLock(supabase, accessToken, {
    orderId,
    lockId,
    bridgeId,
    startDate,
    endDate,
    accessName,
    clearBudgetMs: 50_000,
    createBudgetMs: 60_000,
  });

  if (bridgeResult.lockConfirmed || bridgeResult.jobId) {
    console.log(
      `[generate-pin] Bridge PIN for order #${orderId}: state=${bridgeResult.createState} confirmed=${bridgeResult.lockConfirmed}`,
    );
    return {
      success: true,
      pin: bridgeResult.pin,
      pinId: bridgeResult.jobId,
      pinType: "bridge_proxied",
      startDate,
      endDate,
      lockConfirmed: bridgeResult.lockConfirmed,
      createState: bridgeResult.createState,
      clear: bridgeResult.clear,
      error: bridgeResult.lockConfirmed ? undefined : bridgeResult.error,
    };
  }

  console.warn(`[generate-pin] Bridge failed for order #${orderId}, trying AlgoPIN. Error: ${bridgeResult.error}`);
  const algoResult = await createAlgoPin(
    accessToken,
    lockId,
    booking.drop_off_date,
    booking.drop_off_time_slot,
    booking.pickup_date,
    orderId,
  );
  if (algoResult.success) {
    console.log(`[generate-pin] ✓ AlgoPIN succeeded for order #${orderId}`);
    return {
      success: true,
      pin: algoResult.pin,
      pinId: algoResult.pinId,
      pinType: "algopin",
      startDate,
      endDate,
      lockConfirmed: true,
      createState: "completed",
    };
  }
  return {
    success: false,
    error: `Bridge: ${bridgeResult.error} | AlgoPIN: ${algoResult.error}`,
    startDate,
    endDate,
  };
}
Deno.serve(async (req)=>{
  const corsHeaders = getCorsHeaders(req);
  const jsonResponse = makeJsonResponse(corsHeaders);
  if (req.method === "OPTIONS") return new Response(null, {
    headers: corsHeaders
  });
  if (req.method !== "POST") return jsonResponse({
    success: false,
    error: "Method not allowed"
  }, 405);
  try {
    console.log("[generate-pin] Started:", new Date().toISOString());
    const supabaseUrl = Deno.env.get("SUPABASE_URL");
    const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
    const clientId = Deno.env.get("IGLOOHOME_CLIENT_ID");
    const clientSecret = Deno.env.get("IGLOOHOME_CLIENT_SECRET");
    const lockId = Deno.env.get("IGLOOHOME_LOCK_ID") || Deno.env.get("IGLOOHOME_DEVICE_ID");
    const bridgeId = Deno.env.get("IGLOOHOME_BRIDGE_ID");
    if (!supabaseUrl || !serviceRoleKey || !clientId || !clientSecret || !lockId || !bridgeId) {
      return jsonResponse({
        success: false,
        error: "Missing required environment variables"
      }, 500);
    }
    const supabase = createClient(supabaseUrl, serviceRoleKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false
      }
    });
    // ----------------------------------------------------------------
    // Parse body
    // ----------------------------------------------------------------
    let bookingId = null;
    let callerType = "admin";
    try {
      const body = await req.json();
      bookingId = body.bookingId ?? body.booking_id ?? null;
      callerType = body.callerType ?? "admin";
    } catch  {
      return jsonResponse({
        success: false,
        error: "Invalid or missing JSON body"
      }, 400);
    }
    if (!bookingId) {
      return jsonResponse({
        success: false,
        error: "bookingId is required"
      }, 400);
    }
    console.log("[generate-pin] Caller:", callerType, "BookingId:", bookingId);
    // ----------------------------------------------------------------
    // Auth check
    // ----------------------------------------------------------------
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return jsonResponse({
        success: false,
        error: "Missing Authorization header"
      }, 401);
    }
    const token = authHeader.replace("Bearer ", "");
    const userSupabase = createClient(supabaseUrl, Deno.env.get("SUPABASE_ANON_KEY"), {
      global: {
        headers: {
          Authorization: `Bearer ${token}`
        }
      }
    });
    const { data: { user }, error: authError } = await userSupabase.auth.getUser();
    if (authError || !user) {
      return jsonResponse({
        success: false,
        error: "Unauthorized"
      }, 401);
    }
    if (callerType === "admin") {
      if (user.app_metadata?.is_admin !== true) {
        return jsonResponse({
          success: false,
          error: "Admin access required"
        }, 403);
      }
    }
    if (callerType === "customer") {
      const metadataCustomerId = user.user_metadata?.customer_db_id;
      let customerId = null;

      if (metadataCustomerId != null && metadataCustomerId !== "") {
        const parsed = Number.parseInt(String(metadataCustomerId), 10);
        if (Number.isFinite(parsed)) customerId = parsed;
      }

      if (!customerId) {
        const { data: customer } = await supabase
          .from("customers")
          .select("id")
          .eq("user_id", user.id)
          .maybeSingle();
        customerId = customer?.id ?? null;
      }

      if (!customerId) {
        return jsonResponse({
          success: false,
          error: "Customer not found"
        }, 403);
      }

      const { data: ownerCheck } = await supabase
        .from("bookings")
        .select("id")
        .eq("id", bookingId)
        .eq("customer_id", customerId)
        .maybeSingle();

      if (!ownerCheck) {
        return jsonResponse({
          success: false,
          error: "Booking does not belong to this customer"
        }, 403);
      }
    }
    // ----------------------------------------------------------------
    // Fetch and validate booking
    // ----------------------------------------------------------------
    const { data: booking, error: fetchError } = await supabase
      .from("bookings")
      .select("*")
      .eq("id", bookingId)
      .in("status", ELIGIBLE_BOOKING_STATUSES)
      .single();

    if (fetchError || !booking) {
      return jsonResponse({
        success: false,
        error: "Booking not found or not eligible for PIN generation"
      }, 404);
    }

    if (callerType === "customer") {
      if (isBookingEnded(booking)) {
        return jsonResponse({
          success: false,
          error: "This rental period has ended."
        }, 403);
      }
      if (!isWithinPinGenerationWindow(booking)) {
        return jsonResponse({
          success: false,
          error: "Access PIN is not available yet. Codes are issued 12 hours before your scheduled pickup."
        }, 403);
      }
    }

    // Clear any prior PIN (verified) then create — regeneration is allowed.
    // ----------------------------------------------------------------
    // Generate PIN — bridge first (with verified clear), algopin fallback
    // ----------------------------------------------------------------
    const accessToken = await getOAuthTokenForPin(clientId, clientSecret);
    if (!accessToken) return jsonResponse({
      success: false,
      error: "Failed to get OAuth token"
    }, 500);
    const lockOnline = await isLockOnline(accessToken, lockId);
    console.log(`[generate-pin] Lock online: ${lockOnline}`);
    console.log(`[generate-pin] Booking #${bookingId} | drop_off: ${booking.drop_off_date} ${booking.drop_off_time_slot} | pickup: ${booking.pickup_date} ${booking.pickup_time_slot}`);
    const pinResult = await generatePinWithFallback(accessToken, lockId, bridgeId, supabase, booking);
    if (!pinResult.success) {
      return jsonResponse({
        success: false,
        error: `PIN generation failed: ${pinResult.error}`
      }, 500);
    }
    // ----------------------------------------------------------------
    // Persist — only mark pin_generated_at after a successful insert
    // ----------------------------------------------------------------
    const now = new Date().toISOString();
    const startTimeUTC = pinResult.startDate;
    const endTimeUTC = pinResult.endDate;
    await supabase
      .from("rental_access_codes")
      .update({ status: "expired" })
      .eq("order_id", booking.id)
      .eq("status", "active");
    const { error: insertError } = await supabase.from("rental_access_codes").insert({
      order_id: booking.id,
      customer_email: booking.email,
      customer_phone: booking.phone || "",
      access_pin: pinResult.pin,
      pin_id: pinResult.pinId || "",
      pin_type: pinResult.pinType,
      lock_id: lockId,
      start_time: startTimeUTC,
      end_time: endTimeUTC,
      status: "active",
      lock_confirmed_at: pinResult.lockConfirmed ? now : null,
      confirm_attempts: pinResult.lockConfirmed ? 0 : 1,
    });
    if (insertError) {
      console.error(`[generate-pin] DB insert failed for booking #${bookingId}:`, insertError.message);
      return jsonResponse({
        success: false,
        error: `PIN was created on the lock but failed to save: ${insertError.message}`,
      }, 500);
    }
    await supabase.from("bookings").update({
      pin_generated_at: now
    }).eq("id", bookingId);
    if (pinResult.lockConfirmed) {
      await maybeSendPinNotification(supabase, booking, pinResult.pin, startTimeUTC, endTimeUTC);
    }
    console.log(`[generate-pin] ✓ PIN generated for booking #${bookingId} via ${pinResult.pinType} confirmed=${pinResult.lockConfirmed}`);
    return jsonResponse({
      success: true,
      bookingId,
      pin: pinResult.pin,
      pinType: pinResult.pinType,
      pinId: pinResult.pinId,
      lockConfirmed: !!pinResult.lockConfirmed,
      message: pinResult.lockConfirmed
        ? `PIN generated via ${pinResult.pinType}`
        : `PIN queued via ${pinResult.pinType} — waiting for bridge confirmation`,
    });
  } catch (error) {
    console.error("[generate-pin] Unhandled exception:", error);
    return jsonResponse({
      success: false,
      error: error instanceof Error ? error.message : String(error)
    }, 500);
  }
});

export const PIN_LEAD_TIME_MS = 12 * 60 * 60 * 1000;
/** Extra hour the padlock PIN stays valid after the scheduled booking end. */
export const RETURN_GRACE_MS = 60 * 60 * 1000;
/** Activate the PIN this many ms before drop-off so it works the instant they arrive. */
export const PIN_EARLY_ACTIVATION_MS = 5 * 60 * 1000;

export type BookingWindowFields = {
  drop_off_date?: string | null;
  drop_off_time_slot?: string | null;
  pickup_date?: string | null;
  pickup_time_slot?: string | null;
};

/**
 * Parse a time slot like "6:00 AM" and convert MST -> UTC.
 * MST is UTC-6, so we add 6 hours. Falls back to fallbackHourUTC if unparseable.
 */
export function buildBookingDateUTC(
  date: string,
  timeSlot: string | null | undefined,
  fallbackHourUTC: number,
): string {
  const pad = (n: number) => String(n).padStart(2, "0");

  if (timeSlot) {
    const match = timeSlot.trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
    if (match) {
      let hour = parseInt(match[1], 10);
      const minute = parseInt(match[2], 10);
      const meridiem = match[3].toUpperCase();
      if (meridiem === "PM" && hour !== 12) hour += 12;
      if (meridiem === "AM" && hour === 12) hour = 0;
      const utcHour = hour + 6;
      if (utcHour >= 24) {
        const nextDay = new Date(date + "T00:00:00Z");
        nextDay.setUTCDate(nextDay.getUTCDate() + 1);
        const nextDayStr = nextDay.toISOString().split("T")[0];
        return `${nextDayStr}T${pad(utcHour - 24)}:${pad(minute)}:00+00:00`;
      }
      return `${date}T${pad(utcHour)}:${pad(minute)}:00+00:00`;
    }
  }

  return `${date}T${pad(fallbackHourUTC)}:00:00+00:00`;
}

/** Add RETURN_GRACE_MS to an ISO date string and return a new ISO (+00:00) string. */
export function addGraceHour(isoDate: string): string {
  const ms = new Date(isoDate).getTime() + RETURN_GRACE_MS;
  return new Date(ms).toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

/**
 * Igloohome rejects a duration PIN whose startDate falls before the current hour.
 * Raises a past start up to the top of the current hour; leaves future starts alone.
 */
export function clampIgloohomeStart(isoDate: string, now: Date = new Date()): string {
  const hourFloor = new Date(now.getTime());
  hourFloor.setUTCMinutes(0, 0, 0);
  const ms = Math.max(new Date(isoDate).getTime(), hourFloor.getTime());
  return new Date(ms).toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

export function getBookingWindow(booking: BookingWindowFields) {
  const startIso = buildBookingDateUTC(
    booking.drop_off_date ?? "",
    booking.drop_off_time_slot,
    12,
  );
  const endIso = buildBookingDateUTC(
    booking.pickup_date ?? "",
    booking.pickup_time_slot,
    5,
  );

  const startMs = new Date(startIso).getTime();
  const endMs = new Date(endIso).getTime();
  const graceEndMs = endMs + RETURN_GRACE_MS;
  const graceEndIso = new Date(graceEndMs).toISOString().replace(/\.\d{3}Z$/, "+00:00");
  const activationMs = startMs - PIN_EARLY_ACTIVATION_MS;
  const activationIso = new Date(activationMs).toISOString().replace(/\.\d{3}Z$/, "+00:00");

  return {
    startMs,
    endMs,
    graceEndMs,
    pinEligibleFromMs: startMs - PIN_LEAD_TIME_MS,
    activationMs,
    activationIso,
    startIso,
    endIso,
    graceEndIso,
  };
}

/**
 * PIN start sent to Igloohome: booking drop-off minus 5 minutes, clamped to the
 * current hour so Igloohome accepts it. Customers still see the appointment time.
 */
export function getPinActivationStart(
  booking: BookingWindowFields,
  now: Date = new Date(),
): string {
  const { activationIso } = getBookingWindow(booking);
  return clampIgloohomeStart(activationIso, now);
}

/** Scheduled return time with no grace — for all customer-facing copy. */
export function getCustomerVisibleEndIso(booking: BookingWindowFields): string {
  return getBookingWindow(booking).endIso;
}

export function isWithinPinGenerationWindow(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  if (!booking.drop_off_date || !booking.pickup_date) return false;
  const { pinEligibleFromMs, graceEndMs } = getBookingWindow(booking);
  const nowMs = now.getTime();
  return nowMs >= pinEligibleFromMs && nowMs < graceEndMs;
}

export function isBookingEnded(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  if (!booking.pickup_date) return false;
  const { graceEndMs } = getBookingWindow(booking);
  return now.getTime() >= graceEndMs;
}

export function getPinWindowSkipReason(
  booking: BookingWindowFields,
  now: Date = new Date(),
): "too_early" | "ended" | null {
  if (!booking.drop_off_date || !booking.pickup_date) return "too_early";
  const { pinEligibleFromMs, graceEndMs } = getBookingWindow(booking);
  const nowMs = now.getTime();
  if (nowMs < pinEligibleFromMs) return "too_early";
  if (nowMs >= graceEndMs) return "ended";
  return null;
}

/**
 * Shared Igloohome bridge PIN helpers.
 *
 * A 201 from the bridge only means the job was queued. Deletes and creates must
 * be polled to completion or they silently block each other (bridge ≈ 2 jobs/min).
 * All helpers take a time budget so edge invocations stay under the ~150s gateway limit.
 */

const IGLOOHOME_API_BASE_URL = "https://api.igloodeveloper.co/igloohome";

export type JobState = "completed" | "failed" | "pending";

export type PollResult = {
  state: JobState;
  raw: unknown;
  polls: Array<Record<string, unknown>>;
};

// deno-lint-ignore no-explicit-any
type SupabaseClient = any;

function sleep(ms: number) {
  return new Promise((r) => setTimeout(r, ms));
}

async function readResponse(res: Response) {
  const text = await res.text();
  try {
    return { text, json: text ? JSON.parse(text) : null };
  } catch {
    return { text, json: null };
  }
}

function isoNow() {
  return new Date().toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

/**
 * Poll an Igloohome job until completed/failed or the budget is exhausted.
 * Defaults: 2.5s between polls, ~45s total budget.
 */
export async function pollJob(
  accessToken: string,
  jobId: string,
  budgetMs = 45_000,
  delayMs = 2500,
): Promise<PollResult> {
  const polls: Array<Record<string, unknown>> = [];
  let raw: unknown = null;
  const deadline = Date.now() + budgetMs;
  let attempt = 0;

  while (Date.now() < deadline) {
    attempt += 1;
    await sleep(delayMs);
    if (Date.now() >= deadline && attempt > 1) break;

    const res = await fetch(`${IGLOOHOME_API_BASE_URL}/jobs/${jobId}`, {
      headers: { Authorization: `Bearer ${accessToken}`, Accept: "application/json" },
    });
    const body = await readResponse(res);
    raw = body.json ?? body.text;
    const jobResponse = body.json?.jobResponse;
    const jobStatus = jobResponse?.jobStatus;
    const completed = body.json?.completed;
    polls.push({
      attempt,
      httpStatus: res.status,
      completed: completed ?? null,
      jobStatus: jobStatus ?? null,
    });

    if (completed === true || jobStatus === 0) {
      return { state: "completed", raw, polls };
    }
    if (jobStatus === 2) {
      return { state: "failed", raw, polls };
    }
  }

  return { state: "pending", raw, polls };
}

/** Queue a jobType 5 delete and poll until the lock confirms removal. */
export async function deletePinVerified(
  accessToken: string,
  lockId: string,
  bridgeId: string,
  pin: string,
  budgetMs = 45_000,
): Promise<{ ok: boolean; jobId: string; state: JobState; polls: PollResult["polls"]; error?: string }> {
  const url = `${IGLOOHOME_API_BASE_URL}/devices/${lockId}/jobs/bridges/${bridgeId}`;
  const res = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({ jobType: 5, jobData: { pin } }),
  });
  const body = await readResponse(res);
  if (!res.ok && res.status !== 201) {
    return {
      ok: false,
      jobId: "",
      state: "failed",
      polls: [],
      error: `Delete failed HTTP ${res.status}: ${body.json?.error ?? body.text}`,
    };
  }
  const jobId = String(body.json?.jobId || body.json?.pinId || body.json?.id || "");
  if (!jobId) {
    // Some responses succeed without a jobId — treat as accepted but unverified.
    return { ok: false, jobId: "", state: "pending", polls: [], error: "Delete accepted but no jobId returned" };
  }
  const poll = await pollJob(accessToken, jobId, budgetMs);
  return {
    ok: poll.state === "completed",
    jobId,
    state: poll.state,
    polls: poll.polls,
    error: poll.state === "failed" ? "Lock rejected delete job" : undefined,
  };
}

/**
 * Delete every PIN we've issued for an order that still lacks lock_deleted_at.
 * Only stamps lock_deleted_at when the bridge confirms removal.
 * AlgoPIN rows are marked deleted in DB only (cannot remotely revoke).
 */
export async function clearKnownPins(
  supabase: SupabaseClient,
  accessToken: string,
  orderId: number,
  opts: {
    lockId: string;
    bridgeId: string;
    /** Max ms spent on all deletes combined. */
    budgetMs?: number;
    /** Settle pause between bridge jobs (Igloohome ~2/min). */
    settleMs?: number;
  },
): Promise<{
  attempted: number;
  confirmed: number;
  failed: number;
  pending: number;
  details: Array<Record<string, unknown>>;
}> {
  const budgetMs = opts.budgetMs ?? 60_000;
  const settleMs = opts.settleMs ?? 15_000;
  const deadline = Date.now() + budgetMs;
  const details: Array<Record<string, unknown>> = [];

  const { data: rows } = await supabase
    .from("rental_access_codes")
    .select("id, access_pin, pin_type, status, lock_deleted_at")
    .eq("order_id", orderId)
    .is("lock_deleted_at", null);

  let attempted = 0;
  let confirmed = 0;
  let failed = 0;
  let pending = 0;

  for (const row of rows || []) {
    if (Date.now() >= deadline) {
      pending += 1;
      details.push({ id: row.id, pin: row.access_pin, skipped: true, reason: "budget_exhausted" });
      continue;
    }

    if (row.pin_type === "algopin") {
      // Cannot remotely revoke AlgoPIN; mark DB as deleted so we don't keep trying.
      await supabase
        .from("rental_access_codes")
        .update({
          status: row.status === "active" ? "expired" : row.status,
          lock_deleted_at: new Date().toISOString(),
        })
        .eq("id", row.id);
      confirmed += 1;
      details.push({ id: row.id, pin: row.access_pin, pin_type: "algopin", state: "db_only" });
      continue;
    }

    if (!row.access_pin) continue;
    attempted += 1;
    const remaining = Math.max(5_000, deadline - Date.now());
    const perJobBudget = Math.min(45_000, remaining);
    const result = await deletePinVerified(
      accessToken,
      opts.lockId,
      opts.bridgeId,
      row.access_pin,
      perJobBudget,
    );
    details.push({
      id: row.id,
      pin: row.access_pin,
      jobId: result.jobId,
      state: result.state,
      error: result.error ?? null,
    });

    if (result.ok) {
      confirmed += 1;
      await supabase
        .from("rental_access_codes")
        .update({
          status: "expired",
          lock_deleted_at: new Date().toISOString(),
        })
        .eq("id", row.id);
    } else if (result.state === "failed") {
      failed += 1;
      // Still expire in DB so a new PIN can be issued; lock may need another clear later.
      await supabase
        .from("rental_access_codes")
        .update({ status: "expired" })
        .eq("id", row.id)
        .eq("status", "active");
    } else {
      pending += 1;
      await supabase
        .from("rental_access_codes")
        .update({ status: "expired" })
        .eq("id", row.id)
        .eq("status", "active");
    }

    // Settle between bridge jobs when more remain.
    if (Date.now() + settleMs < deadline && attempted < (rows || []).length) {
      await sleep(settleMs);
    }
  }

  return { attempted, confirmed, failed, pending, details };
}

/** Queue a jobType 4 custom-duration PIN and poll until the lock confirms. */
export async function createPinVerified(
  accessToken: string,
  lockId: string,
  bridgeId: string,
  pin: string,
  startDate: string,
  endDate: string,
  accessName: string,
  budgetMs = 60_000,
): Promise<{
  success: boolean;
  pin: string;
  jobId: string;
  state: JobState;
  polls: PollResult["polls"];
  raw: unknown;
  error?: string;
}> {
  const url = `${IGLOOHOME_API_BASE_URL}/devices/${lockId}/jobs/bridges/${bridgeId}`;
  const res = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      jobType: 4,
      jobData: { accessName, pin, pinType: 4, startDate, endDate },
    }),
  });
  const body = await readResponse(res);
  if (!res.ok && res.status !== 201) {
    return {
      success: false,
      pin,
      jobId: "",
      state: "failed",
      polls: [],
      raw: body.json ?? body.text,
      error: `Create failed HTTP ${res.status}: ${body.json?.error ?? body.text}`,
    };
  }
  const jobId = String(body.json?.jobId || body.json?.pinId || body.json?.id || "");
  if (!jobId) {
    return {
      success: false,
      pin,
      jobId: "",
      state: "pending",
      polls: [],
      raw: body.json,
      error: "Create accepted but no jobId returned",
    };
  }
  const poll = await pollJob(accessToken, jobId, budgetMs);
  return {
    success: poll.state === "completed",
    pin,
    jobId,
    state: poll.state,
    polls: poll.polls,
    raw: poll.raw,
    error: poll.state === "failed"
      ? "Lock rejected PIN create job"
      : poll.state === "pending"
        ? "Bridge has not confirmed PIN delivery yet"
        : undefined,
  };
}

export type EnsurePinResult = {
  success: boolean;
  pin: string;
  jobId: string;
  pinType: "bridge_proxied";
  startDate: string;
  endDate: string;
  lockConfirmed: boolean;
  clear: Awaited<ReturnType<typeof clearKnownPins>>;
  createState: JobState;
  polls: PollResult["polls"];
  error?: string;
};

/**
 * Clear known PINs (verified), then create a new bridge PIN and poll for confirmation.
 * Bounded: clear budget + create budget should stay under ~120s total.
 */
export async function ensurePinOnLock(
  supabase: SupabaseClient,
  accessToken: string,
  opts: {
    orderId: number;
    lockId: string;
    bridgeId: string;
    pin?: string;
    startDate: string;
    endDate: string;
    accessName: string;
    clearBudgetMs?: number;
    createBudgetMs?: number;
    settleMs?: number;
  },
): Promise<EnsurePinResult> {
  const pin = opts.pin || String(Math.floor(Math.random() * 900000) + 100000);
  const clear = await clearKnownPins(supabase, accessToken, opts.orderId, {
    lockId: opts.lockId,
    bridgeId: opts.bridgeId,
    budgetMs: opts.clearBudgetMs ?? 50_000,
    settleMs: opts.settleMs ?? 15_000,
  });

  // If a delete is still pending, wait a short settle then proceed — create may still
  // fail if the old PIN is on the lock, but the watchdog will retry.
  if (clear.pending > 0) {
    await sleep(opts.settleMs ?? 15_000);
  }

  const created = await createPinVerified(
    accessToken,
    opts.lockId,
    opts.bridgeId,
    pin,
    opts.startDate,
    opts.endDate,
    opts.accessName,
    opts.createBudgetMs ?? 60_000,
  );

  return {
    success: created.state === "completed",
    pin,
    jobId: created.jobId,
    pinType: "bridge_proxied",
    startDate: opts.startDate,
    endDate: opts.endDate,
    lockConfirmed: created.state === "completed",
    clear,
    createState: created.state,
    polls: created.polls,
    error: created.error,
  };
}

export { isoNow, IGLOOHOME_API_BASE_URL };

/**
 * Shared Igloohome OAuth (client_credentials).
 *
 * Cognito rejects the entire token exchange (HTTP 400 invalid_request) if any
 * requested scope is not authorized on the app client. Request the full set
 * first, then drop known-optional scopes, then omit scope entirely so Cognito
 * grants whatever the client actually owns.
 */

export const IGLOOHOME_OAUTH_URL = "https://auth.igloohome.co/oauth2/token";

/** Scopes used by bridge PIN create/delete + job polling + device listing. */
export const BRIDGE_PIN_SCOPES = [
  "igloohomeapi/create-pin-bridge-proxied-job",
  "igloohomeapi/delete-pin-bridge-proxied-job",
  "igloohomeapi/get-devices",
  "igloohomeapi/get-job-status",
  "igloohomeapi/store-device-activity",
] as const;

/** Scopes used by generate-pin / AlgoPIN production path. */
export const GENERATE_PIN_SCOPES = [
  "igloohomeapi/create-pin-bridge-proxied-job",
  "igloohomeapi/get-devices",
  "igloohomeapi/get-job-status",
  "igloohomeapi/algopin-onetime",
  "igloohomeapi/store-device-activity",
] as const;

/**
 * Legacy umbrella scope — newer Igloohome apps use per-job scopes instead
 * (e.g. create-pin-bridge-proxied-job, get-activity-logs-bridge-proxied-job).
 * Including an unauthorized scope causes Cognito to reject the whole exchange.
 */
export const OPTIONAL_OAUTH_SCOPES = [
  "igloohomeapi/create-bridge-proxied-job",
] as const;

export type OAuthResult = { token: string | null; reason?: string; scopesUsed?: string };

/** Correct scope for bridge activity-log jobs (jobType 15). */
export const ACTIVITY_SYNC_SCOPE = "igloohomeapi/get-activity-logs-bridge-proxied-job";

/**
 * Scope for GET /devices/{id}/activity.
 * Empirically this endpoint 403s unless the access token was issued with ONLY
 * this scope (mixing it with get-activity-logs-bridge-proxied-job or using an
 * unscoped "all owned scopes" grant returns 403).
 */
export const DEVICE_ACTIVITY_SCOPE = "igloohomeapi/get-device-activity";

/** Scopes required to pull lock activity logs (jobType 15). */
export const ACTIVITY_SYNC_SCOPES = [
  ACTIVITY_SYNC_SCOPE,
  "igloohomeapi/get-devices",
  "igloohomeapi/get-job-status",
  "igloohomeapi/store-device-activity",
] as const;

export const ACTIVITY_SYNC_SCOPE_HINT =
  "Enable the Igloohome API scope igloohomeapi/get-activity-logs-bridge-proxied-job on your developer credentials " +
  "(https://web.igloohome.co/api/). PIN create uses create-pin-bridge-proxied-job and can work without it; " +
  "Sync Lock Activity (jobType 15) cannot. Until then, use Simulate Unlock / Simulate Lock in the test lab.";

export const DEVICE_ACTIVITY_SCOPE_HINT =
  "Enable igloohomeapi/get-device-activity on your Igloohome developer credentials " +
  "(https://web.igloohome.co/api/). Sync needs it to read unlock/lock history after the Bridge pull.";

/** Decode Cognito access-token scope claim (space-separated). */
export function tokenScopes(accessToken: string): string[] {
  try {
    const payload = accessToken.split(".")[1];
    if (!payload) return [];
    const normalized = payload.replace(/-/g, "+").replace(/_/g, "/");
    const json = JSON.parse(atob(normalized));
    return String(json.scope || "").split(/\s+/).filter(Boolean);
  } catch {
    return [];
  }
}

export function tokenHasScope(accessToken: string, scope: string): boolean {
  return tokenScopes(accessToken).includes(scope);
}

/**
 * Token for activity-log sync. Requires get-activity-logs-bridge-proxied-job —
 * do not silently fall back to a weaker token that will only 403 on jobType 15.
 */
export async function getActivitySyncToken(
  clientId: string,
  clientSecret: string,
): Promise<OAuthResult> {
  // Prefer an explicit grant that includes the required scope.
  const explicit = await requestOAuthToken(clientId, clientSecret, ACTIVITY_SYNC_SCOPES);
  if (explicit.token && tokenHasScope(explicit.token, ACTIVITY_SYNC_SCOPE)) {
    return explicit;
  }

  const onlyRequired = await requestOAuthToken(clientId, clientSecret, [ACTIVITY_SYNC_SCOPE]);
  if (onlyRequired.token && tokenHasScope(onlyRequired.token, ACTIVITY_SYNC_SCOPE)) {
    return onlyRequired;
  }

  // Unscoped grant = every scope the app client owns.
  const unscoped = await requestOAuthToken(clientId, clientSecret, []);
  if (unscoped.token && tokenHasScope(unscoped.token, ACTIVITY_SYNC_SCOPE)) {
    return unscoped;
  }

  if (unscoped.token && !tokenHasScope(unscoped.token, ACTIVITY_SYNC_SCOPE)) {
    return {
      token: null,
      reason: `OAuth succeeded but the token does not include ${ACTIVITY_SYNC_SCOPE}. ${ACTIVITY_SYNC_SCOPE_HINT}`,
      scopesUsed: unscoped.scopesUsed,
    };
  }

  return {
    token: null,
    reason: `${onlyRequired.reason || explicit.reason || "OAuth failed"}. ${ACTIVITY_SYNC_SCOPE_HINT}`,
    scopesUsed: onlyRequired.scopesUsed || explicit.scopesUsed,
  };
}

/**
 * Token for GET /devices/{id}/activity. Must be a solo-scope grant — see
 * DEVICE_ACTIVITY_SCOPE comment.
 */
export async function getDeviceActivityToken(
  clientId: string,
  clientSecret: string,
): Promise<OAuthResult> {
  const only = await requestOAuthToken(clientId, clientSecret, [DEVICE_ACTIVITY_SCOPE]);
  if (only.token && tokenHasScope(only.token, DEVICE_ACTIVITY_SCOPE)) {
    return only;
  }
  return {
    token: null,
    reason: `${only.reason || "OAuth failed"}. ${DEVICE_ACTIVITY_SCOPE_HINT}`,
    scopesUsed: only.scopesUsed,
  };
}


async function readResponse(res: Response) {
  const text = await res.text();
  try {
    return { text, json: text ? JSON.parse(text) : null };
  } catch {
    return { text, json: null };
  }
}

export async function requestOAuthToken(
  clientId: string,
  clientSecret: string,
  scopes: readonly string[] = BRIDGE_PIN_SCOPES,
): Promise<OAuthResult> {
  const credentials = btoa(`${clientId}:${clientSecret}`);
  const form = new URLSearchParams({ grant_type: "client_credentials" });
  if (scopes.length) form.set("scope", scopes.join(" "));

  let res: Response;
  try {
    res = await fetch(IGLOOHOME_OAUTH_URL, {
      method: "POST",
      headers: {
        Authorization: `Basic ${credentials}`,
        "Content-Type": "application/x-www-form-urlencoded",
        Accept: "application/json",
      },
      body: form,
    });
  } catch (err) {
    return { token: null, reason: `network error reaching auth.igloohome.co: ${err}` };
  }

  const body = await readResponse(res);
  if (!res.ok || !body.json?.access_token) {
    const detail = body.json?.error_description || body.json?.error || body.text ||
      "(empty response)";
    return {
      token: null,
      reason: `Igloohome OAuth HTTP ${res.status}: ${String(detail).slice(0, 300)}`,
      scopesUsed: scopes.length ? scopes.join(" ") : "(none)",
    };
  }
  return {
    token: body.json.access_token as string,
    scopesUsed: scopes.length ? scopes.join(" ") : "(none — Cognito default grant)",
  };
}

/**
 * Obtain an access token, falling back when optional scopes are unauthorized.
 */
export async function getOAuthToken(
  clientId: string,
  clientSecret: string,
  scopes: readonly string[] = BRIDGE_PIN_SCOPES,
): Promise<OAuthResult> {
  const full = await requestOAuthToken(clientId, clientSecret, scopes);
  if (full.token) return full;

  const optional = new Set<string>(OPTIONAL_OAUTH_SCOPES);
  const reduced = scopes.filter((s) => !optional.has(s));
  if (reduced.length && reduced.length !== scopes.length) {
    const retry = await requestOAuthToken(clientId, clientSecret, reduced);
    if (retry.token) return retry;
  }

  // Prefer a grant that explicitly includes algopin when the caller asked for it,
  // without the unauthorized create-bridge-proxied-job scope.
  if (scopes.includes("igloohomeapi/algopin-onetime")) {
    const algoOnly = [
      "igloohomeapi/algopin-onetime",
      "igloohomeapi/get-devices",
      "igloohomeapi/get-job-status",
    ];
    const algo = await requestOAuthToken(clientId, clientSecret, algoOnly);
    if (algo.token) return algo;
  }

  // Omitting scope entirely makes Cognito grant every scope the app client owns.
  const unscoped = await requestOAuthToken(clientId, clientSecret, []);
  if (unscoped.token) return unscoped;

  return full;
}

export type DiagnoseRow = {
  scopes: string;
  ok: boolean;
  reason: string | null;
};

/** Probe several scope sets. Never returns tokens. */
export async function diagnoseOAuth(
  clientId: string,
  clientSecret: string,
): Promise<DiagnoseRow[]> {
  const cases: Array<{ label: string; scopes: readonly string[] }> = [
    { label: "no scope requested (Cognito grants all owned)", scopes: [] },
    { label: "bridge PIN set (setup/clear)", scopes: BRIDGE_PIN_SCOPES },
    { label: "generate-pin / AlgoPIN set", scopes: GENERATE_PIN_SCOPES },
    { label: "activity sync set (jobType 15)", scopes: ACTIVITY_SYNC_SCOPES },
    {
      label: "create-pin + get-devices",
      scopes: [
        "igloohomeapi/create-pin-bridge-proxied-job",
        "igloohomeapi/get-devices",
      ],
    },
    { label: "only igloohomeapi/algopin-onetime", scopes: ["igloohomeapi/algopin-onetime"] },
    { label: `only ${ACTIVITY_SYNC_SCOPE}`, scopes: [ACTIVITY_SYNC_SCOPE] },
    { label: `only ${DEVICE_ACTIVITY_SCOPE}`, scopes: [DEVICE_ACTIVITY_SCOPE] },
    { label: "only igloohomeapi/create-bridge-proxied-job (legacy)", scopes: ["igloohomeapi/create-bridge-proxied-job"] },
    ...BRIDGE_PIN_SCOPES.map((s) => ({ label: `only ${s}`, scopes: [s] as const })),
  ];

  const results: DiagnoseRow[] = [];
  for (const c of cases) {
    const r = await requestOAuthToken(clientId, clientSecret, c.scopes);
    results.push({
      scopes: c.label,
      ok: !!r.token,
      reason: r.token ? null : (r.reason ?? "unknown"),
    });
  }
  return results;
}

/** Human-readable hint when Igloohome returns bridge unreachable. */
export function bridgeOfflineHint(errorText: string | undefined | null): string | null {
  const t = String(errorText || "");
  if (/unable to contact bridge|bridge.*offline|406/i.test(t)) {
    return (
      "Igloohome's cloud cannot reach your Bridge right now. " +
      "An empty PIN list in the Igloo app does not mean the Bridge is online — " +
      "check Bridge power/Wi‑Fi, wait ~1 minute after it reconnects, then retry. " +
      "Meanwhile use Setup + AlgoPIN (works offline)."
    );
  }
  return null;
}

const ALLOWED_HEADERS = 'authorization, x-client-info, apikey, content-type';
const ALLOWED_METHODS = 'GET, POST, PUT, PATCH, DELETE, OPTIONS';

function parseAllowedOrigins(): Set<string> {
  const raw = Deno.env.get('ALLOWED_ORIGINS') ?? '';
  return new Set(
    raw
      .split(',')
      .map((origin) => origin.trim())
      .filter(Boolean),
  );
}

let cachedOrigins: Set<string> | null = null;

function getAllowedOrigins(): Set<string> {
  if (!cachedOrigins) {
    cachedOrigins = parseAllowedOrigins();
  }
  return cachedOrigins;
}

/** Origin-aware CORS headers. Set ALLOWED_ORIGINS (comma-separated) in env. */
export function getCorsHeaders(req: Request): Record<string, string> {
  const headers: Record<string, string> = {
    'Access-Control-Allow-Headers': ALLOWED_HEADERS,
    'Access-Control-Allow-Methods': ALLOWED_METHODS,
  };

  const origin = req.headers.get('Origin');
  if (origin && getAllowedOrigins().has(origin)) {
    headers['Access-Control-Allow-Origin'] = origin;
    headers['Vary'] = 'Origin';
  }

  return headers;
}
